async function readJson(response: Response) {
  const body = await response.text();
  if (!body) return { error: response.ok ? "The service returned no data." : "The service is temporarily unavailable. Please try again." };
  try { return JSON.parse(body); }
  catch { return { error: "The service returned an unexpected response. Please try again." }; }
}
