export default function Home() {
  const [mode, setMode] = useState<"customer" | "dealer" | "kiosk" | "staff" | "display" | "analytics" | "launch">("customer");
  const [step, setStep] = useState(1);
  const [service, setService] = useState<ServiceKey | null>(null);
  const [subtype, setSubtype] = useState("");
  const [checked, setChecked] = useState<string[]>([]);
  const [validated, setValidated] = useState<string[]>([]);
  const [location, setLocation] = useState("Las Vegas — West Flamingo");
  const [showPass, setShowPass] = useState(false);
  const [passCode, setPassCode] = useState("");
  const [passLoading, setPassLoading] = useState(false);
  const [passError, setPassError] = useState("");
  const [passStatus, setPassStatus] = useState("ready");
  const [passCounter, setPassCounter] = useState("");
  const [identityConfirmed, setIdentityConfirmed] = useState(false);
  const [accessOpen, setAccessOpen] = useState(false);
  const [largeText, setLargeText] = useState(false);
  const [highContrast, setHighContrast] = useState(false);
  const [feedbackSent, setFeedbackSent] = useState(false);
  const [appointmentDate, setAppointmentDate] = useState("");
  const [appointmentTime, setAppointmentTime] = useState("");
  const [reminderSaved, setReminderSaved] = useState(false);
  const [lang, setLang] = useState<"en" | "es">("en");
  const [hydrated, setHydrated] = useState(false);
  const [operationsAllowed, setOperationsAllowed] = useState(false);
  const [operationsChecked, setOperationsChecked] = useState(false);
  const [operationsNotice, setOperationsNotice] = useState(false);
  const list = useMemo(() => service ? checklists[service] : [], [service]);
  const progress = [0,20,40,65,85,100][step];
  const ready = list.length > 0 && checked.length === list.length;
  const requiredChecks = transactionChecks[subtype] || [];
  const transactionValidated = requiredChecks.length === 0 || validated.length === requiredChecks.length;
  const selectedOffice = offices.find(office=>office.name===location) || offices[0];
  const tr = (value:string) => lang === "es" ? spanish[value] || value : value;
  const reset = () => { setStep(1); setService(null); setSubtype(""); setChecked([]); setValidated([]); setShowPass(false); setPassCode(""); setPassError(""); setPassStatus("ready"); setPassCounter(""); setIdentityConfirmed(false); setFeedbackSent(false); setAppointmentDate(""); setAppointmentTime(""); setReminderSaved(false); localStorage.removeItem("fastlane-progress"); };
  const chooseService = (key: ServiceKey) => { setService(key); setSubtype(""); setChecked([]); setValidated([]); setStep(2); };
  const toggle = (item: string) => setChecked(v => v.includes(item) ? v.filter(x => x !== item) : [...v, item]);
  useEffect(() => {
    try {
      const saved = JSON.parse(localStorage.getItem("fastlane-progress") || "null");
      if (saved) { setStep(saved.step || 1); setService(saved.service || null); setSubtype(saved.subtype || ""); setChecked(saved.checked || []); setValidated(saved.validated || []); setLocation(saved.location === "Las Vegas — Flamingo" ? "Las Vegas — West Flamingo" : saved.location || "Las Vegas — West Flamingo"); setLang(saved.lang || "en"); setAppointmentDate(saved.appointmentDate || ""); setAppointmentTime(saved.appointmentTime || ""); }
    } catch {}
    setHydrated(true);
  }, []);
  useEffect(() => {
    if (hydrated && service) localStorage.setItem("fastlane-progress", JSON.stringify({step, service, subtype, checked, validated, location, lang, appointmentDate, appointmentTime}));
  }, [hydrated, step, service, subtype, checked, validated, location, lang, appointmentDate, appointmentTime]);
  useEffect(() => {
    let active = true;
    fetch("/api/operations-access", { cache: "no-store" })
      .then(readJson)
      .then((data) => { if (active) setOperationsAllowed(Boolean(data.allowed)); })
      .catch(() => { if (active) setOperationsAllowed(false); })
      .finally(() => { if (active) setOperationsChecked(true); });
    return () => { active = false; };
  }, []);
  useEffect(() => {
    if (operationsChecked && !operationsAllowed && ["dealer", "staff", "display", "analytics", "launch"].includes(mode)) setMode("customer");
  }, [mode, operationsAllowed, operationsChecked]);
  useEffect(() => {
    if (!passCode) return;
    const check=async()=>{try{const r=await fetch(`/api/visits?code=${encodeURIComponent(passCode)}`);const d=await readJson(r);if(r.ok&&d.visit){setPassStatus(d.visit.status);setPassCounter(d.visit.serviceCounter||"");}}catch{}};
    check(); const timer=setInterval(check,10000); return()=>clearInterval(timer);
  },[passCode]);
  async function createPass() {
    if (!service) return;
    setPassLoading(true); setPassError("");
    try {
      const response = await fetch("/api/visits", { method:"POST", headers:{"content-type":"application/json"}, body:JSON.stringify({service, subtype, location, documentsConfirmed:checked.length, transactionConfirmed:transactionValidated}) });
      const data = await readJson(response);
      if (!response.ok) throw new Error(data.error || "Unable to create pass");
      setPassCode(data.visit.code); setPassStatus(data.visit.status); setShowPass(true);
    } catch (error) { setPassError(error instanceof Error ? error.message : "Unable to create pass"); }
    finally { setPassLoading(false); }
  }
  function addCalendarReminder() {
    if (!appointmentDate || !appointmentTime) return;
    const start = `${appointmentDate.replaceAll("-","")}T${appointmentTime.replace(":","")}00`;
    const startDate = new Date(`${appointmentDate}T${appointmentTime}:00`);
    const endDate = new Date(startDate.getTime()+30*60000);
    const pad=(n:number)=>String(n).padStart(2,"0");
    const end=`${endDate.getFullYear()}${pad(endDate.getMonth()+1)}${pad(endDate.getDate())}T${pad(endDate.getHours())}${pad(endDate.getMinutes())}00`;
    const safe=(v:string)=>v.replaceAll("\\","\\\\").replaceAll(",","\\,").replaceAll(";","\\;").replaceAll("\n","\\n");
    const ics=["BEGIN:VCALENDAR","VERSION:2.0","PRODID:-//Nevada FastLane//Appointment//EN","BEGIN:VEVENT",`UID:${crypto.randomUUID()}@fastlane`,`DTSTAMP:${new Date().toISOString().replace(/[-:]/g,"").replace(/\.\d{3}/,"")}`,`DTSTART:${start}`,`DTEND:${end}`,`SUMMARY:${safe("Nevada DMV appointment")}`,`LOCATION:${safe(location)}`,`DESCRIPTION:${safe(`FastLane visit: ${subtype}. Bring original documents and your readiness pass. Plan to arrive 15 minutes early.`)}`,"BEGIN:VALARM","TRIGGER:-PT24H","ACTION:DISPLAY","DESCRIPTION:Nevada DMV appointment tomorrow","END:VALARM","END:VEVENT","END:VCALENDAR"].join("\r\n");
    const url=URL.createObjectURL(new Blob([ics],{type:"text/calendar;charset=utf-8"})); const anchor=document.createElement("a"); anchor.href=url; anchor.download="nevada-dmv-appointment.ics"; document.body.appendChild(anchor); anchor.click(); anchor.remove(); URL.revokeObjectURL(url); setReminderSaved(true);
  }

  return <main className={`min-h-screen bg-[var(--background)] text-[var(--foreground)] ${largeText?"large-text":""} ${highContrast?"high-contrast":""}`}>
    <a href="#main-content" className="skip-link">Skip to main content</a>
    <header className="sticky top-0 z-20 border-b border-[var(--border)] bg-white/95 backdrop-blur"><div className="mx-auto flex max-w-6xl items-center justify-between px-4 py-3 sm:px-6"><button onClick={reset} className="brand-home flex items-center gap-3 text-left" aria-label="Nevada DMV FastLane home"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[var(--primary)] text-white"><ShieldCheck size={23}/></span><span><strong className="block text-[17px] leading-5">Nevada FastLane</strong><small className="text-[13px] text-[var(--muted-foreground)]">DMV visit assistant</small></span></button><div className="header-actions flex gap-2"><button onClick={()=>setAccessOpen(v=>!v)} className="header-pill" aria-label="Accessibility settings" aria-expanded={accessOpen}><Accessibility size={17}/><span className="hidden sm:inline">Accessibility</span></button><button onClick={() => setLang(v => v === "en" ? "es" : "en")} className="header-pill" aria-label={lang === "en" ? "Cambiar a Español" : "Switch to English"}><Languages size={16}/><span>{lang === "en" ? "Español" : "English"}</span></button><button className="header-pill" aria-label="Nevada location"><MapPin size={16}/><span className="hidden sm:inline">{tr("Nevada")}</span></button></div></div>{accessOpen&&<div className="border-t border-[var(--border)] bg-white"><div className="mx-auto grid max-w-6xl gap-2 px-4 py-3 sm:grid-cols-2 sm:px-6"><button onClick={()=>setLargeText(v=>!v)} className={`access-button ${largeText?"active":""}`} aria-pressed={largeText}><Accessibility size={20}/> Larger words <strong>{largeText?"On":"Off"}</strong></button><button onClick={()=>setHighContrast(v=>!v)} className={`access-button ${highContrast?"active":""}`} aria-pressed={highContrast}><Eye size={20}/> High contrast <strong>{highContrast?"On":"Off"}</strong></button></div></div>}</header>
    <div id="main-content" className="mx-auto max-w-6xl px-4 py-6 sm:px-6 sm:py-9" tabIndex={-1}>
      <div className="mb-3 grid grid-cols-2 gap-1 rounded-2xl bg-[#e9eef4] p-1 sm:grid-cols-4 lg:max-w-6xl lg:grid-cols-7"><button onClick={() => setMode("customer")} className={`mode-button ${mode === "customer" ? "active" : ""}`}><Users size={18}/> {tr("Customer")}</button><button onClick={() => setMode("kiosk")} className={`mode-button ${mode === "kiosk" ? "active" : ""}`}><MonitorSmartphone size={18}/> {tr("Kiosk")}</button>{operationsAllowed?<><button onClick={() => setMode("dealer")} className={`mode-button ${mode === "dealer" ? "active" : ""}`}><Store size={18}/> {tr("Dealership")}</button><button onClick={() => setMode("staff")} className={`mode-button ${mode === "staff" ? "active" : ""}`}><UserCog size={18}/> Staff</button><button onClick={() => setMode("display")} className={`mode-button ${mode === "display" ? "active" : ""}`}><Tv size={18}/> Lobby display</button><button onClick={() => setMode("analytics")} className={`mode-button ${mode === "analytics" ? "active" : ""}`}><BarChart3 size={18}/> Pilot data</button><button onClick={() => setMode("launch")} className={`mode-button ${mode === "launch" ? "active" : ""}`}><Rocket size={18}/> Pilot launch</button></>:<button onClick={()=>setOperationsNotice(v=>!v)} className="mode-button"><LockKeyhole size={18}/> {operationsChecked?"Operations":"Checking access"}</button>}</div>
      {operationsAllowed&&<div className="mb-6 flex w-fit items-center gap-2 rounded-full bg-emerald-100 px-4 py-2 text-sm font-black text-emerald-900"><LockKeyhole size={17}/> Authorized operations</div>}
      {operationsNotice&&!operationsAllowed&&<div role="status" className="mb-6 flex max-w-2xl gap-3 rounded-2xl border-2 border-amber-200 bg-amber-50 p-4 text-amber-950"><LockKeyhole className="shrink-0"/><div><strong className="block text-lg">DMV operations are protected</strong><p className="mt-1 text-sm font-semibold">Dealership queues, staff controls, lobby displays and pilot reporting are available only to authorized accounts.</p></div></div>}
      {mode === "dealer" ? <DealerView/> : mode === "kiosk" ? <KioskView lang={lang}/> : mode === "staff" ? <StaffView/> : mode === "display" ? <LobbyDisplay/> : mode === "analytics" ? <AnalyticsView/> : mode === "launch" ? <PilotLaunchView/> : <>
        <section className="mb-6 rounded-[28px] bg-[var(--navy)] p-6 text-white shadow-xl shadow-blue-950/10 sm:p-9"><div className="flex flex-col justify-between gap-6 md:flex-row md:items-end"><div><p className="mb-2 text-sm font-bold uppercase tracking-[.16em] text-[#8cc8ff]">{tr("Prepare before you go")}</p><h1 className="max-w-2xl text-3xl font-bold tracking-tight sm:text-4xl">{tr("Make one DMV visit count.")}</h1><p className="mt-3 max-w-2xl text-base leading-7 text-blue-100">{tr("Find the correct process, confirm every document and arrive with a readiness pass for faster check-in.")}</p></div><div className="min-w-56 rounded-2xl bg-white/10 p-4"><div className="mb-2 flex justify-between text-sm"><span>{tr("Visit readiness")}</span><strong>{progress}%</strong></div><div className="h-2 overflow-hidden rounded-full bg-white/15"><div className="h-full rounded-full bg-[#ffbd32] transition-all" style={{width:`${progress}%`}}/></div><div className="mt-3 flex items-center gap-2 text-xs text-blue-100"><CheckCircle2 size={15}/>{tr("Saved on this device")}</div></div></div></section>
        {step === 1 && <section><p className="eyebrow">{lang==="es"?"Paso 1 de 5":"Step 1 of 5"}</p><h2 className="section-title mb-5">{tr("What do you need to do?")}</h2><div className="grid gap-3 md:grid-cols-2 lg:grid-cols-3">{services.map(({key,name,detail,icon:Icon}) => <button key={key} onClick={() => chooseService(key)} className="service-card"><span className="service-icon"><Icon size={25}/></span><span className="min-w-0 flex-1"><strong>{tr(name)}</strong><small>{tr(detail)}</small></span><ArrowRight className="text-[#708196]" size={20}/></button>)}</div></section>}
        {step === 2 && service && <section className="panel"><button onClick={() => setStep(1)} className="back"><ArrowLeft size={17}/> {tr("Change service")}</button><p className="eyebrow">{lang==="es"?"Paso 2 de 5":"Step 2 of 5"}</p><h2 className="section-title">{tr("Choose your exact transaction")}</h2><p className="mb-5 mt-2 text-[var(--muted-foreground)]">{tr("Your answer changes the documents and next steps we show you.")}</p><div className="grid gap-3 sm:grid-cols-2">{subtypes[service].map(item => <button key={item} onClick={() => {setSubtype(item);setValidated([]);}} className={`choice-card ${subtype === item ? "selected" : ""}`}><span>{tr(item)}</span>{subtype === item && <CheckCircle2 size={20}/>}</button>)}</div>{subtype&&transactionGuidance[subtype]&&<div className="mt-5 rounded-2xl border-2 border-blue-200 bg-blue-50 p-4 text-blue-950"><div className="flex gap-3"><ShieldCheck className="shrink-0"/><div><strong className="block text-lg">Fastest verified path</strong><p className="mt-1 text-sm font-semibold leading-6">{transactionGuidance[subtype].message}</p><a href={transactionGuidance[subtype].url} target="_blank" rel="noreferrer" className="mt-3 inline-flex items-center gap-2 font-black text-[var(--primary)]">{transactionGuidance[subtype].action}<ExternalLink size={16}/></a></div></div></div>}<button disabled={!subtype} onClick={() => setStep(3)} className="primary-button mt-5">{tr("Continue")} <ArrowRight size={18}/></button></section>}
        {step === 3 && service && <section className="panel"><button onClick={() => setStep(2)} className="back"><ArrowLeft size={17}/> {tr("Transaction")}</button><p className="eyebrow">{lang==="es"?"Paso 3 de 5":"Step 3 of 5"}</p><h2 className="section-title">{tr("Confirm your documents")}</h2><p className="mb-5 mt-2 text-[var(--muted-foreground)]">{tr("Check only documents you already have as valid originals or certified copies.")}</p><div className="mb-4 rounded-xl bg-blue-50 px-4 py-3 text-sm font-bold text-blue-900">{tr(subtype)}</div><div className="space-y-3">{list.map(item => <button key={item} onClick={() => toggle(item)} className={`check-row ${checked.includes(item) ? "checked" : ""}`}><span className="checkbox">{checked.includes(item) && <Check size={17}/>}</span><span>{tr(item)}</span></button>)}</div>{requiredChecks.length>0&&<div className="mt-6 rounded-2xl border-2 border-amber-200 bg-amber-50 p-4"><p className="eyebrow text-amber-800">Transaction validation</p><h3 className="mb-3 text-xl font-black text-amber-950">Confirm these requirements</h3><div className="space-y-3">{requiredChecks.map(item=><button key={item} onClick={()=>setValidated(value=>value.includes(item)?value.filter(entry=>entry!==item):[...value,item])} className={`check-row bg-white ${validated.includes(item)?"checked":""}`}><span className="checkbox">{validated.includes(item)&&<Check size={17}/>}</span><span>{item}</span></button>)}</div></div>}<div className={`mt-5 rounded-2xl p-4 ${ready&&transactionValidated ? "bg-emerald-50 text-emerald-900" : "bg-amber-50 text-amber-950"}`}><div className="flex gap-3">{ready&&transactionValidated ? <CheckCircle2/> : <Clock3/>}<div><strong className="block">{ready&&transactionValidated ? "Documents and transaction checks complete" : "More confirmation is required"}</strong><span className="text-sm">{tr("FastLane guides preparation; Nevada DMV makes the final eligibility decision.")}</span></div></div></div><button disabled={!ready||!transactionValidated} onClick={() => setStep(4)} className="primary-button mt-5">{tr("Continue to appointment")} <ArrowRight size={18}/></button></section>}
        {step === 4 && <section className="panel"><button onClick={() => setStep(3)} className="back"><ArrowLeft size={17}/> Documents</button><p className="eyebrow">{lang==="es"?"Paso 4 de 5":"Step 4 of 5"}</p><h2 className="section-title">{tr("Choose where you’ll go")}</h2><label className="mt-5 block text-sm font-bold" htmlFor="office">{tr("DMV office")}</label><select id="office" value={location} onChange={e => setLocation(e.target.value)} className="mt-2 w-full rounded-xl border border-[var(--border)] bg-white px-4 py-3 text-base"><optgroup label={lang==="es"?"Oficinas metropolitanas":"Metropolitan offices"}>{offices.filter(office=>!("rural" in office)).map(office=><option key={office.name}>{office.name}</option>)}</optgroup><optgroup label={lang==="es"?"Oficinas rurales":"Rural offices"}>{offices.filter(office=>"rural" in office).map(office=><option key={office.name}>{office.name}</option>)}</optgroup></select><div className="mt-4 rounded-2xl border-2 border-[var(--border)] bg-white p-4"><div className="flex gap-3"><span className="service-icon"><MapPin size={24}/></span><div><strong className="block text-lg text-[#0a2947]">{selectedOffice.name}</strong><span className="mt-1 block text-[var(--muted-foreground)]">{selectedOffice.address}</span></div></div><div className="mt-4 grid gap-2 text-sm font-bold sm:grid-cols-2"><span className="rounded-xl bg-[var(--muted)] p-3"><Clock3 className="mr-2 inline" size={17}/>{selectedOffice.hours}</span><span className="rounded-xl bg-[var(--muted)] p-3"><Car className="mr-2 inline" size={17}/>{selectedOffice.features}</span></div><a href={selectedOffice.map} target="_blank" rel="noreferrer" className="secondary-button mt-4"><Navigation size={18}/> {lang==="es"?"Obtener indicaciones":"Get directions"} <ExternalLink size={16}/></a><p className="mt-3 text-sm font-bold text-amber-900">{lang==="es"?"Se requiere cita. Verifique los horarios antes de viajar.":"Appointment required. Confirm current hours before traveling."}</p></div><div className="mt-4 rounded-2xl border border-blue-200 bg-blue-50 p-4"><strong className="flex items-center gap-2 text-[#073b70]"><CalendarCheck size={20}/> {tr("Appointment handoff")}</strong><p className="mt-2 text-sm leading-6 text-[#315b82]">FastLane will send you to Nevada DMV’s official scheduling system. Return here afterward to record the appointment and create your check-in pass.</p></div><a href="https://dmv.nv.gov/appointments.htm" target="_blank" rel="noreferrer" className="primary-button mt-5">{tr("Open official DMV scheduling")} <ArrowRight size={18}/></a><div className="mt-5 rounded-2xl bg-[var(--muted)] p-4"><strong className="flex items-center gap-2 text-[#0a2947]"><Clock3 size={20}/> {tr("Record your appointment")}</strong><p className="mt-1 text-sm text-[var(--muted-foreground)]">{tr("Optional. These details stay on this device and create your calendar reminder.")}</p><div className="mt-4 grid gap-3 sm:grid-cols-2"><label className="font-bold">{tr("Date")}<input type="date" value={appointmentDate} onChange={e=>{setAppointmentDate(e.target.value);setReminderSaved(false)}} className="mt-2 block w-full rounded-xl border-2 border-[var(--border)] bg-white px-4 py-3"/></label><label className="font-bold">{tr("Time")}<input type="time" value={appointmentTime} onChange={e=>{setAppointmentTime(e.target.value);setReminderSaved(false)}} className="mt-2 block w-full rounded-xl border-2 border-[var(--border)] bg-white px-4 py-3"/></label></div></div><button onClick={() => setStep(5)} className="secondary-button mt-3">{appointmentDate&&appointmentTime?tr("I scheduled my appointment"):tr("Continue without appointment details")}</button></section>}
        {step === 5 && <section className="panel"><p className="eyebrow">{lang==="es"?"Paso 5 de 5":"Step 5 of 5"}</p><h2 className="section-title">{tr("You’re ready to visit")}</h2><div className="mt-5 grid gap-4 sm:grid-cols-3"><Summary icon={FileCheck2} label={tr("Transaction")} value={tr(subtype)}/><Summary icon={MapPin} label={tr("Office")} value={location}/><Summary icon={CheckCircle2} label={tr("Documents")} value={`${checked.length} ${tr("confirmed")}`}/></div>{appointmentDate&&appointmentTime&&<div className="mt-4 flex gap-3 rounded-2xl bg-amber-50 p-4 text-amber-950"><CalendarCheck className="shrink-0"/><div><strong className="block">{new Date(`${appointmentDate}T${appointmentTime}`).toLocaleString([], {dateStyle:"long",timeStyle:"short"})}</strong><span className="text-sm">Plan to arrive 15 minutes early with your original documents and FastLane pass.</span></div></div>}<button onClick={()=>setIdentityConfirmed(v=>!v)} className={`check-row mt-5 ${identityConfirmed?"checked":""}`} aria-pressed={identityConfirmed}><span className="checkbox">{identityConfirmed&&<Check size={17}/>}</span><span><strong className="block">{tr("Identity confirmation")}</strong><small className="mt-1 block font-semibold text-[var(--muted-foreground)]">{tr("I am the person using this pass and will bring my original identity documents.")}</small></span></button><div className="mt-4 flex gap-3 rounded-2xl bg-blue-50 p-4 text-blue-950"><LockKeyhole className="mt-1 shrink-0" size={22}/><p className="text-sm"><strong className="block">{tr("Your privacy is protected")}</strong>FastLane does not collect Social Security numbers, birth dates, license numbers, document images or payment details. This readiness pass is not an official identity credential.</p></div><div className="mt-5 grid gap-3 sm:grid-cols-2"><button onClick={createPass} disabled={passLoading || Boolean(passCode) || !identityConfirmed} className="primary-button">{passLoading ? <Loader2 className="animate-spin" size={20}/> : <QrCode size={19}/>} {passCode ? "Pass created" : tr("Create readiness pass")}</button><button onClick={addCalendarReminder} disabled={!appointmentDate||!appointmentTime} className="secondary-button"><Bell size={18}/> {tr(reminderSaved?"Calendar file created":"Add calendar reminder")}</button></div>{reminderSaved&&<p role="status" className="mt-3 rounded-xl bg-emerald-50 p-3 font-bold text-emerald-900">Open the downloaded calendar file to save the appointment and 24-hour alert.</p>}{!identityConfirmed&&!passCode&&<p className="mt-3 text-sm font-bold text-[var(--muted-foreground)]">{tr("Confirm your identity responsibility to create the pass.")}</p>}{passError && <p role="alert" className="mt-4 rounded-xl bg-red-50 p-3 font-bold text-red-800">{passError}</p>}{showPass && passCode && <div className="mt-5 rounded-3xl border-2 border-[var(--primary)] bg-white p-5 text-center" aria-live="polite"><div className="mx-auto mb-3 grid h-28 w-28 place-items-center rounded-xl bg-[#071b34] text-white"><QrCode size={78}/></div><p className="eyebrow">{tr("FastLane pass")}</p><h3 className="text-xl font-bold">{passStatus==="called"?`Proceed to ${passCounter}`:passStatus==="complete"?tr("Transaction complete"):passStatus==="checked_in"?tr("You’re checked in"):tr("Show this pass at check-in")}</h3><p className="mt-2 text-lg font-black tracking-wide text-[var(--primary)]">{passCode}</p><div className={`mx-auto mt-4 flex max-w-sm items-center justify-center gap-2 rounded-xl p-3 font-black capitalize ${passStatus==="called"?"bg-amber-100 text-amber-950":passStatus==="complete"?"bg-emerald-100 text-emerald-900":"bg-blue-50 text-blue-900"}`}>{passStatus==="called"?<Navigation size={20}/>:<RefreshCw size={18}/>} {passStatus.replace("_"," ")}{passCounter?` · ${passCounter}`:""}</div><p className="mt-3 text-sm text-[var(--muted-foreground)]">{tr("Status updates automatically every 10 seconds.")}</p></div>}{passStatus==="complete"&&!feedbackSent&&<FeedbackSurvey code={passCode} lang={lang} onSent={()=>setFeedbackSent(true)}/>} {feedbackSent&&<div className="mt-5 rounded-2xl bg-emerald-50 p-5 text-center text-emerald-900"><CheckCircle2 className="mx-auto mb-2"/><strong className="text-lg">Thank you for helping improve FastLane.</strong></div>}<button onClick={reset} className="mt-5 flex items-center gap-2 text-sm font-bold text-[var(--primary)]"><RotateCcw size={17}/>{tr("Start over")}</button></section>}
      </>}
    </div>
  </main>;
}

function Summary({icon:Icon,label,value}:{icon:typeof IdCard,label:string,value:string}) { return <div className="rounded-2xl bg-[var(--muted)] p-4"><Icon size={21} className="mb-3 text-[var(--primary)]"/><small className="block text-[13px] text-[var(--muted-foreground)]">{label}</small><strong className="mt-1 block text-sm">{value}</strong></div> }
function KioskView({lang}:{lang:"en"|"es"}) {
  const [code,setCode]=useState(""); const [done,setDone]=useState(false); const [queue,setQueue]=useState(""); const [status,setStatus]=useState("checked_in"); const [counter,setCounter]=useState(""); const [error,setError]=useState(""); const [loading,setLoading]=useState(false);
  const es=lang==="es";
  useEffect(()=>{if(!done||!code)return;const check=async()=>{try{const r=await fetch(`/api/visits?code=${encodeURIComponent(code)}`);const d=await readJson(r);if(r.ok&&d.visit){setStatus(d.visit.status);setCounter(d.visit.serviceCounter||"");}}catch{}};check();const timer=setInterval(check,7000);return()=>clearInterval(timer);},[done,code]);
  async function checkIn(){const fallback=es?"El registro no está disponible temporalmente. Pida ayuda a un empleado del DMV.":"Check-in is temporarily unavailable. Please ask a DMV team member for help.";setLoading(true);setError("");try{const response=await fetch("/api/visits",{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({code})});const data=await readJson(response);if(!response.ok||!data.visit)throw new Error(data.error&&data.error!=="The service is temporarily unavailable. Please try again."?data.error:fallback);setQueue(data.visit.queueNumber);setDone(true);}catch(e){setError(e instanceof Error?e.message:fallback);}finally{setLoading(false);}}
  return <section className="kiosk-panel"><div className="mx-auto max-w-xl text-center"><span className="mx-auto grid h-16 w-16 place-items-center rounded-2xl bg-blue-100 text-[var(--primary)]"><MonitorSmartphone size={34}/></span><p className="eyebrow mt-5">{es?"Registro en el vestíbulo":"Lobby check-in"}</p><h1 className="section-title">{done ? (status==="called"?(es?`Diríjase a ${counter}`:`Proceed to ${counter}`):(es?"Registro completado":"You’re checked in")) : (es?"Ingrese su código FastLane":"Enter your FastLane code")}</h1>{done ? <><div className={`mx-auto mt-6 grid h-24 w-24 place-items-center rounded-full ${status==="called"?"bg-amber-100 text-amber-800":"bg-emerald-100 text-emerald-700"}`}>{status==="called"?<Navigation size={48}/>:<Check size={48}/>}</div><p className="mt-5 text-lg">Queue <strong>{queue}</strong></p><p className="mt-2 text-[var(--muted-foreground)]">{status==="called"?(es?`Es su turno. Vaya a ${counter}.`:`It’s your turn. Please go to ${counter}.`):(es?"Tome asiento. Le avisaremos cuando sea su turno.":"Please take a seat. This screen updates automatically when it’s your turn.")}</p><button onClick={()=>{setDone(false);setCode("");setQueue("");setStatus("checked_in");setCounter("");}} className="secondary-button mt-6">{es?"Siguiente cliente":"Next customer"}</button></> : <><p className="mx-auto mt-3 max-w-md text-[var(--muted-foreground)]">{es?"Use el código de su pase de preparación o escanee su código QR.":"Use the code on your readiness pass or scan its QR code."}</p><input value={code} onChange={e=>setCode(e.target.value.toUpperCase())} placeholder="NV-TITLE-482190" className="mt-6 w-full rounded-2xl border-2 border-[var(--border)] px-5 py-4 text-center text-xl font-bold uppercase tracking-wider" aria-label="FastLane code"/>{error&&<p className="mt-3 rounded-xl bg-red-50 p-3 font-bold text-red-800">{error}</p>}<button disabled={code.length<8||loading} onClick={checkIn} className="primary-button mt-4">{loading?<Loader2 className="animate-spin" size={20}/>:null}{es?"Registrarme":"Check me in"} <ArrowRight size={19}/></button><button className="secondary-button mt-3"><QrCode size={19}/>{es?"Escanear código QR":"Scan QR code"}</button><p className="mt-6 text-sm text-[var(--muted-foreground)]">{es?"¿No tiene pase? Seleccione Cliente arriba para prepararse.":"No pass yet? Select Customer above to prepare."}</p></>}</div></section>
}
type VisitRow={code:string;subtype:string;location:string;status:string;queueNumber?:string|null;serviceCounter?:string|null};
function DealerView() {
  const [rows,setRows]=useState<VisitRow[]>([]); const [loading,setLoading]=useState(true);
  async function load(){setLoading(true);try{const response=await fetch("/api/visits");const data=await response.json();setRows(data.visits||[]);}finally{setLoading(false);}}
  useEffect(()=>{load();},[]);
  const ready=rows.filter(r=>r.status==="ready").length, checked=rows.filter(r=>r.status==="checked_in").length;
  return <section><div className="mb-5 flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="eyebrow">Dealer workspace</p><h1 className="section-title">Shared readiness queue</h1><p className="mt-2 text-[var(--muted-foreground)]">Live customer passes and kiosk check-ins appear here.</p></div><button onClick={load} className="primary-button sm:w-auto"><RefreshCw className={loading?"animate-spin":""} size={18}/> Refresh queue</button></div><div className="grid gap-3 sm:grid-cols-3"><Summary icon={FileCheck2} label="Total passes" value={String(rows.length)}/><Summary icon={CheckCircle2} label="Ready to arrive" value={String(ready)}/><Summary icon={Clock3} label="Checked in" value={String(checked)}/></div><div className="mt-5 overflow-hidden rounded-2xl border border-[var(--border)] bg-white"><div className="hidden grid-cols-[1.2fr_1.5fr_1.3fr_1fr] gap-4 border-b bg-[var(--muted)] px-5 py-3 text-sm font-bold sm:grid"><span>Pass</span><span>Transaction</span><span>Office</span><span>Status</span></div>{loading&&<div className="flex items-center justify-center gap-2 p-8"><Loader2 className="animate-spin"/> Loading queue</div>}{!loading&&!rows.length&&<div className="p-8 text-center text-[var(--muted-foreground)]">No customer passes yet.</div>}{rows.map(r=><div key={r.code} className="grid gap-1 border-b border-[var(--border)] px-5 py-4 last:border-0 sm:grid-cols-[1.2fr_1.5fr_1.3fr_1fr] sm:items-center sm:gap-4"><strong>{r.code}</strong><span>{r.subtype}</span><span className="text-sm text-[var(--muted-foreground)]">{r.location}</span><span className={`mt-1 w-fit rounded-full px-3 py-1 text-xs font-bold sm:mt-0 ${r.status==="checked_in"?"bg-blue-100 text-blue-800":"bg-emerald-100 text-emerald-800"}`}>{r.status==="checked_in"?`Checked in · ${r.queueNumber}`:"Ready"}</span></div>)}</div></section>
}

function StaffView() {
  const [rows,setRows]=useState<VisitRow[]>([]); const [loading,setLoading]=useState(true); const [busy,setBusy]=useState("");
  async function load(){setLoading(true);try{const r=await fetch("/api/visits");const d=await r.json();setRows(d.visits||[]);}finally{setLoading(false);}}
  useEffect(()=>{load();const timer=setInterval(load,15000);return()=>clearInterval(timer);},[]);
  async function update(code:string,action:"call"|"complete",counter?:string){setBusy(code);try{await fetch("/api/visits",{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({code,action,counter})});await load();}finally{setBusy("");}}
  const waiting=rows.filter(r=>r.status==="checked_in"), called=rows.filter(r=>r.status==="called"), complete=rows.filter(r=>r.status==="complete");
  const next=waiting[waiting.length-1];
  return <section>
    <div className="mb-5 flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="eyebrow">DMV operations</p><h1 className="section-title">Live service queue</h1><p className="mt-2 text-[var(--muted-foreground)]">Call customers, direct them to a counter and complete transactions.</p></div><button onClick={load} className="secondary-button sm:w-auto"><RefreshCw className={loading?"animate-spin":""} size={19}/> Refresh</button></div>
    <div className="grid gap-3 sm:grid-cols-3"><Summary icon={Clock3} label="Waiting" value={String(waiting.length)}/><Summary icon={Megaphone} label="Now serving" value={String(called.length)}/><Summary icon={BadgeCheck} label="Completed" value={String(complete.length)}/></div>
    {next&&<div className="mt-5 rounded-3xl bg-[var(--navy)] p-6 text-white"><p className="text-sm font-black uppercase tracking-widest text-blue-200">Next customer</p><div className="mt-2 flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><strong className="block text-4xl">{next.queueNumber}</strong><span className="mt-2 block text-blue-100">{next.subtype} · {next.location}</span></div><div className="grid grid-cols-2 gap-2 sm:flex">{["Counter 1","Counter 2","Counter 3"].map(counter=><button key={counter} disabled={busy===next.code} onClick={()=>update(next.code,"call",counter)} className="rounded-xl bg-white px-4 py-3 font-black text-[#073b70] hover:bg-blue-50">{counter}</button>)}</div></div></div>}
    <div className="mt-5 overflow-hidden rounded-2xl border border-[var(--border)] bg-white"><div className="grid grid-cols-[.7fr_1.3fr_1fr] gap-3 border-b bg-[var(--muted)] px-5 py-3 font-black sm:grid-cols-[.7fr_1.3fr_1fr_1fr]"><span>Queue</span><span>Transaction</span><span>Status</span><span className="hidden sm:block">Action</span></div>{loading&&!rows.length&&<div className="flex justify-center gap-2 p-8"><Loader2 className="animate-spin"/>Loading</div>}{rows.filter(r=>r.status!=="ready").map(r=><div key={r.code} className="grid grid-cols-[.7fr_1.3fr_1fr] items-center gap-3 border-b px-5 py-4 last:border-0 sm:grid-cols-[.7fr_1.3fr_1fr_1fr]"><strong>{r.queueNumber||"—"}</strong><span>{r.subtype}</span><span className="font-bold capitalize">{r.status==="called"?r.serviceCounter:r.status.replace("_"," ")}</span><div className="col-span-3 sm:col-span-1">{r.status==="called"&&<button disabled={busy===r.code} onClick={()=>update(r.code,"complete")} className="secondary-button !min-h-11 !text-sm"><CheckCircle2 size={17}/> Complete</button>}</div></div>)}</div>
  </section>
}

function LobbyDisplay() {
  const [rows,setRows]=useState<VisitRow[]>([]);
  useEffect(()=>{const load=async()=>{try{const r=await fetch("/api/visits");const d=await r.json();setRows(d.visits||[]);}catch{}};load();const timer=setInterval(load,7000);return()=>clearInterval(timer);},[]);
  const called=rows.filter(r=>r.status==="called").slice(0,3);
  const waiting=rows.filter(r=>r.status==="checked_in").slice(-8).reverse();
  return <section className="overflow-hidden rounded-[2rem] bg-[var(--navy)] text-white shadow-2xl">
    <div className="border-b border-white/15 px-6 py-5 sm:px-9"><div className="flex items-center justify-between"><div><p className="text-sm font-black uppercase tracking-[.18em] text-blue-200">Nevada FastLane</p><h1 className="mt-1 text-3xl font-black">Now serving / Ahora atendiendo</h1></div><div className="hidden items-center gap-2 rounded-full bg-emerald-400/15 px-4 py-2 font-bold text-emerald-200 sm:flex"><span className="h-3 w-3 animate-pulse rounded-full bg-emerald-400"/> Live</div></div></div>
    <div className="grid gap-6 p-6 sm:p-9 lg:grid-cols-[1.4fr_.8fr]">
      <div><p className="mb-4 font-black uppercase tracking-widest text-blue-200">Please proceed to your counter</p><div className="space-y-4">{!called.length&&<div className="rounded-3xl bg-white/8 p-10 text-center text-xl text-blue-100">Waiting for the next customer</div>}{called.map(r=><div key={r.code} className="flex items-center justify-between rounded-3xl bg-[#ffbd32] p-6 text-[#071f3c] shadow-xl"><strong className="text-4xl sm:text-6xl">{r.queueNumber}</strong><div className="text-right"><span className="block text-sm font-black uppercase tracking-wider">Proceed to</span><strong className="text-2xl sm:text-4xl">{r.serviceCounter}</strong></div></div>)}</div></div>
      <div className="rounded-3xl bg-white/8 p-5"><p className="mb-4 font-black uppercase tracking-widest text-blue-200">Waiting / En espera</p><div className="grid grid-cols-2 gap-3">{waiting.map(r=><div key={r.code} className="rounded-2xl border border-white/15 bg-white/8 p-4 text-center text-2xl font-black">{r.queueNumber}</div>)}{!waiting.length&&<p className="col-span-2 py-8 text-center text-blue-100">No customers waiting</p>}</div></div>
    </div>
  </section>
}

const launchChecks = [
  {group:"Systems",items:["Customer preparation opens on a phone", "Kiosk accepts a valid readiness code", "Staff queue and counter actions are authorized", "Lobby display is visible from the waiting area"]},
  {group:"People",items:["Pilot lead and backup lead are assigned", "Front-desk and counter staff completed the quick briefing", "Staff know when to use the manual-queue fallback"]},
  {group:"Customer experience",items:["Entrance signage explains FastLane check-in", "English and Spanish assistance is available", "Accessibility settings and an assisted path were verified"]},
  {group:"Operations",items:["Opening, during-day and closing owners are assigned", "Issue log and escalation contact are ready"]},
];

function PilotLaunchView() {
  const allItems=launchChecks.flatMap(section=>section.items);
  const [completed,setCompleted]=useState<string[]>([]);
  useEffect(()=>{try{const saved=JSON.parse(localStorage.getItem("fastlane-launch-checks")||"[]");if(Array.isArray(saved))setCompleted(saved.filter(item=>allItems.includes(item)));}catch{}},[]);
  useEffect(()=>{localStorage.setItem("fastlane-launch-checks",JSON.stringify(completed));},[completed]);
  const toggleItem=(item:string)=>setCompleted(value=>value.includes(item)?value.filter(entry=>entry!==item):[...value,item]);
  const percent=Math.round(completed.length/allItems.length*100);
  const ready=completed.length===allItems.length;
  return <section className="launch-sheet">
    <div className="mb-6 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="eyebrow">Final launch package</p><h1 className="section-title">Nevada FastLane pilot center</h1><p className="mt-2 max-w-3xl text-[var(--muted-foreground)]">Use this protected checklist for opening-day approval, staff coordination and consistent daily operation.</p></div><button onClick={()=>window.print()} className="secondary-button print-button sm:w-auto"><Printer size={19}/> Print quick-start</button></div>
    <div className={`mb-6 rounded-3xl p-6 ${ready?"bg-emerald-700 text-white":"bg-[var(--navy)] text-white"}`}><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-center"><div><p className="text-sm font-black uppercase tracking-[.16em] text-blue-100">Go-live decision</p><h2 className="mt-1 text-3xl font-black">{ready?"Ready to launch":"Launch checks in progress"}</h2><p className="mt-2 text-blue-100">{completed.length} of {allItems.length} required checks complete</p></div><strong className="text-5xl">{percent}%</strong></div><div className="mt-5 h-3 overflow-hidden rounded-full bg-white/20"><div className="h-full rounded-full bg-[#ffbd32] transition-all" style={{width:`${percent}%`}}/></div></div>
    <div className="grid gap-5 lg:grid-cols-[1.25fr_.75fr]">
      <div className="space-y-5">{launchChecks.map(section=><div key={section.group} className="rounded-3xl border border-[var(--border)] bg-white p-5 sm:p-6"><div className="mb-4 flex items-center gap-3"><span className="service-icon"><ClipboardCheck size={25}/></span><h2 className="text-xl font-black text-[#0a2947]">{section.group}</h2></div><div className="space-y-3">{section.items.map(item=><button key={item} onClick={()=>toggleItem(item)} className={`check-row ${completed.includes(item)?"checked":""}`} aria-pressed={completed.includes(item)}><span className="checkbox">{completed.includes(item)&&<Check size={17}/>}</span><span>{item}</span></button>)}</div></div>)}</div>
      <aside className="space-y-5">
        <div className="rounded-3xl border border-[var(--border)] bg-white p-5"><h2 className="flex items-center gap-2 text-xl font-black text-[#0a2947]"><Clock3/> Daily playbook</h2><div className="mt-4 space-y-4 text-sm leading-6"><div><strong className="block text-base">15 minutes before opening</strong>Open the kiosk, staff queue and lobby display. Complete one test check-in.</div><div><strong className="block text-base">During service</strong>Watch waiting customers, resolve document exceptions and record recurring issues.</div><div><strong className="block text-base">At closing</strong>Complete active visits, review pilot data and note fixes for the next day.</div></div></div>
        <div className="rounded-3xl bg-blue-50 p-5 text-blue-950"><h2 className="flex items-center gap-2 text-xl font-black"><BarChart3/> Proposed pilot targets</h2><ul className="mt-4 space-y-3 text-sm font-bold"><li>• 80%+ arrive with all listed documents</li><li>• Under 2 minutes for FastLane check-in</li><li>• 25% fewer avoidable document returns</li><li>• 4.0/5 or higher customer rating</li></ul></div>
        <div className="rounded-3xl border-2 border-amber-200 bg-amber-50 p-5 text-amber-950"><h2 className="flex items-center gap-2 text-xl font-black"><AlertTriangle/> Escalation guide</h2><div className="mt-4 space-y-3 text-sm"><p><strong>Critical:</strong> Security concern or queue failure—pause digital check-in and use the manual queue.</p><p><strong>Service:</strong> Kiosk or display issue—continue counter service and notify the pilot lead.</p><p><strong>Content:</strong> Incorrect requirement—direct the customer to official DMV guidance and log the correction.</p></div></div>
        <div className="rounded-3xl bg-[var(--navy)] p-5 text-white"><h2 className="flex items-center gap-2 text-xl font-black"><ShieldCheck/> Staff quick rules</h2><ul className="mt-4 space-y-3 text-sm text-blue-100"><li>Never enter SSNs, license numbers or payment details.</li><li>FastLane supports preparation; DMV staff make final eligibility decisions.</li><li>Use only authorized staff controls for queue actions and reporting.</li></ul></div>
      </aside>
    </div>
  </section>
}

function FeedbackSurvey({code,lang,onSent}:{code:string;lang:"en"|"es";onSent:()=>void}) {
  const [rating,setRating]=useState(0); const [issue,setIssue]=useState("none"); const [busy,setBusy]=useState(false); const [error,setError]=useState("");
  async function submit(){setBusy(true);setError("");try{const r=await fetch("/api/feedback",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({code,rating,issue})});const d=await r.json();if(!r.ok)throw new Error(d.error||"Unable to send feedback");onSent();}catch(e){setError(e instanceof Error?e.message:"Unable to send feedback");}finally{setBusy(false);}}
  const es=lang==="es";
  return <div className="mt-5 rounded-3xl border-2 border-[#bdd7ee] bg-[#f5faff] p-5 text-left"><div className="flex gap-3"><span className="service-icon"><MessageSquareText size={24}/></span><div><p className="eyebrow">{es?"Encuesta de un minuto":"One-minute survey"}</p><h3 className="text-xl font-black text-[#0a2947]">{es?"¿Cómo fue su visita con FastLane?":"How was your FastLane visit?"}</h3></div></div><div className="mt-5 flex justify-center gap-2" role="group" aria-label={es?"Calificación de cinco estrellas":"Rating out of five"}>{[1,2,3,4,5].map(value=><button key={value} onClick={()=>setRating(value)} className={`rating-button ${rating>=value?"active":""}`} aria-label={es?`${value} estrella${value===1?"":"s"}`:`${value} star${value===1?"":"s"}`} aria-pressed={rating===value}><Star size={27} fill={rating>=value?"currentColor":"none"}/></button>)}</div><label className="mt-5 block font-black" htmlFor="feedback-issue">{es?"¿Qué podría mejorar?":"What could be better?"} <span className="font-semibold text-[var(--muted-foreground)]">{es?"Opcional":"Optional"}</span></label><select id="feedback-issue" value={issue} onChange={e=>setIssue(e.target.value)} className="mt-2 w-full rounded-xl border-2 border-[var(--border)] bg-white px-4 py-3 font-bold"><option value="none">{es?"Nada — todo salió bien":"Nothing — everything went well"}</option><option value="instructions">{es?"Las instrucciones no estaban claras":"Instructions were unclear"}</option><option value="documents">{es?"Orientación sobre documentos":"Document guidance"}</option><option value="wait">{es?"Tiempo de espera":"Wait time"}</option><option value="accessibility">{es?"Accesibilidad":"Accessibility"}</option><option value="other">{es?"Otra cosa":"Something else"}</option></select>{error&&<p role="alert" className="mt-3 rounded-xl bg-red-50 p-3 font-bold text-red-800">{error}</p>}<button disabled={!rating||busy} onClick={submit} className="primary-button mt-4">{busy?<Loader2 className="animate-spin" size={19}/>:<MessageSquareText size={19}/>} {es?"Enviar opinión":"Send feedback"}</button><p className="mt-3 text-center text-sm text-[var(--muted-foreground)]">{es?"No se recopilan nombres, correos electrónicos ni comentarios escritos.":"No name, email or written comments are collected."}</p></div>
}

type AnalyticsData={window:string;summary:{total:number;completed:number;waiting:number;serving:number;averageMinutes:number};locations:{location:string;total:number;completed:number}[];services:{service:string;total:number}[];feedback:{responses:number;averageRating:number;positive:number;issues:{issue:string;total:number}[]}};
const serviceNames:Record<string,string>={license:"Driver’s license & ID",registration:"Vehicle registration",title:"Title transfer",test:"Written & road tests",appointment:"Appointments & check-in"};
function AnalyticsView() {
  const [data,setData]=useState<AnalyticsData|null>(null); const [loading,setLoading]=useState(true); const [error,setError]=useState("");
  async function load(){setLoading(true);setError("");try{const r=await fetch("/api/visits?analytics=1");const d=await r.json();if(!r.ok)throw new Error(d.error||"Unable to load pilot data");setData(d);}catch(e){setError(e instanceof Error?e.message:"Unable to load pilot data");}finally{setLoading(false);}}
  useEffect(()=>{load();const timer=setInterval(load,30000);return()=>clearInterval(timer);},[]);
  const maxLocation=Math.max(1,...(data?.locations||[]).map(item=>Number(item.total))); const maxService=Math.max(1,...(data?.services||[]).map(item=>Number(item.total)));
  return <section>
    <div className="mb-5 flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="eyebrow">Pilot performance</p><h1 className="section-title">FastLane operations snapshot</h1><p className="mt-2 text-[var(--muted-foreground)]">Live demand and service outcomes across participating Nevada DMV offices.</p></div><button onClick={load} className="secondary-button sm:w-auto"><RefreshCw className={loading?"animate-spin":""} size={19}/> Refresh data</button></div>
    {error&&<p className="mb-5 rounded-2xl bg-red-50 p-4 font-bold text-red-800">{error}</p>}
    {!data&&loading?<div className="flex items-center justify-center gap-3 rounded-3xl bg-white p-12 font-bold"><Loader2 className="animate-spin"/> Loading pilot data</div>:data&&<>
      <div className="mb-3 flex items-center gap-2 text-sm font-bold text-[var(--muted-foreground)]"><Clock3 size={17}/>{data.window} · updates every 30 seconds</div>
      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><Summary icon={Users} label="Customer visits" value={String(data.summary.total)}/><Summary icon={BadgeCheck} label="Completed" value={String(data.summary.completed)}/><Summary icon={Clock3} label="Waiting now" value={String(data.summary.waiting)}/><Summary icon={Timer} label="Average completion" value={data.summary.completed?`${data.summary.averageMinutes} min`:"—"}/></div>
      <div className="mt-5 rounded-3xl bg-[var(--navy)] p-5 text-white sm:p-6"><div className="grid gap-5 sm:grid-cols-[auto_1fr] sm:items-center"><div className="grid h-20 w-20 place-items-center rounded-2xl bg-[#ffbd32] text-[#071f3c]"><Star size={38} fill="currentColor"/></div><div><p className="text-sm font-black uppercase tracking-widest text-blue-200">Customer experience</p><div className="mt-1 flex flex-wrap items-baseline gap-x-6 gap-y-2"><strong className="text-4xl">{data.feedback.responses?`${data.feedback.averageRating} / 5`:"No ratings yet"}</strong><span className="font-bold text-blue-100">{data.feedback.responses} responses · {data.feedback.responses?Math.round(data.feedback.positive/data.feedback.responses*100):0}% positive</span></div></div></div>{data.feedback.issues.length>0&&<div className="mt-5 border-t border-white/15 pt-4"><strong>Top improvement signals: </strong>{data.feedback.issues.map(item=>`${item.issue} (${Number(item.total)})`).join(" · ")}</div>}</div>
      <div className="mt-6 grid gap-5 lg:grid-cols-2">
        <div className="rounded-3xl border border-[var(--border)] bg-white p-5 sm:p-6"><div className="mb-5 flex items-center gap-3"><span className="service-icon"><Building2 size={23}/></span><div><h2 className="text-xl font-black">Office activity</h2><p className="text-sm text-[var(--muted-foreground)]">Visits and completions by location</p></div></div><div className="space-y-5">{!data.locations.length&&<p className="rounded-2xl bg-[var(--muted)] p-6 text-center text-[var(--muted-foreground)]">No visits recorded in this period.</p>}{data.locations.map(item=><div key={item.location}><div className="mb-2 flex items-end justify-between gap-4"><div><strong className="block">{item.location}</strong><span className="text-sm text-[var(--muted-foreground)]">{Number(item.completed)} completed</span></div><strong className="text-xl">{Number(item.total)}</strong></div><div className="h-3 overflow-hidden rounded-full bg-[#e9eef4]"><div className="h-full rounded-full bg-[var(--primary)]" style={{width:`${Math.max(8,Number(item.total)/maxLocation*100)}%`}}/></div></div>)}</div></div>
        <div className="rounded-3xl border border-[var(--border)] bg-white p-5 sm:p-6"><div className="mb-5 flex items-center gap-3"><span className="service-icon"><BarChart3 size={23}/></span><div><h2 className="text-xl font-black">Service demand</h2><p className="text-sm text-[var(--muted-foreground)]">Customer volume by transaction</p></div></div><div className="space-y-5">{!data.services.length&&<p className="rounded-2xl bg-[var(--muted)] p-6 text-center text-[var(--muted-foreground)]">Demand will appear as customers create passes.</p>}{data.services.map(item=><div key={item.service}><div className="mb-2 flex justify-between gap-4"><strong>{serviceNames[item.service]||item.service}</strong><strong>{Number(item.total)}</strong></div><div className="h-3 overflow-hidden rounded-full bg-[#e9eef4]"><div className="h-full rounded-full bg-[#ffbd32]" style={{width:`${Math.max(8,Number(item.total)/maxService*100)}%`}}/></div></div>)}</div></div>
      </div>
      <div className="mt-5 rounded-2xl bg-blue-50 p-4 text-sm text-blue-950"><strong>{data.summary.serving} now serving.</strong> This dashboard reports operational pilot activity only and does not display customer personal information.</div>
    </>}
  </section>
}
